sys_ws_operation.operation_script:
(function process(request, response) {
    if (!(gs.hasRole('x_espaco.recepcionista') || gs.hasRole('x_espaco.gestor') || gs.hasRole('x_espaco.admin'))) {
        response.setStatus(403);
        return { error: { code: 403, message: 'Sem permissão para executar esta operação.' } };
    }
    var id = request.pathParams.id;
    var body = request.body.data || {};
    var gr = new GlideRecord('x_espaco_agendamento');
    if (!gr.get(id)) {
        response.setStatus(404);
        return { error: { code: 404, message: 'Agendamento não encontrado.' } };
    }
    if (body.dataHora) {
        gr.setValue('data_hora', body.dataHora);
        gr.setValue('status', 'reagendado');
    }
    if (body.status) {
        gr.setValue('status', body.status);
    }
    if (!gr.update()) {
        response.setStatus(409);
        return { error: { code: 409, message: 'Conflito ao atualizar agendamento.' } };
    }
    response.setStatus(200);
    return { data: { sys_id: id, status: gr.getValue('status') } };
})(request, response);
